 LinearLayout shell,player,settings; TextView track,artist,clock; ImageView cover; SeekBar progress; android.os.Handler ui=new android.os.Handler(); int shown=-1; boolean dragging=false; int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} 
 android.graphics.drawable.GradientDrawable bg(int a,int b,int radius){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{a,b});g.setCornerRadius(dp(radius));return g;}
 TextView label(String t,int size){TextView v=new TextView(this);v.setText(t);v.setTextSize(size);v.setTextColor(-1);return v;}
 void action(LinearLayout row,String t,Runnable f){TextView v=label(t,16);v.setGravity(17);v.setPadding(dp(12),dp(12),dp(12),dp(12));v.setBackground(bg(0xff303746,0xff222936,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(v,lp);v.setOnClickListener(w->f.run());}
 void showPage(boolean setup){settings.setVisibility(setup?0:8);player.setVisibility(setup?8:0);p.edit().putBoolean("setupPage",setup).apply();}
 void buildPlayer(){boolean wide=getResources().getConfiguration().orientation==2;player=new LinearLayout(this);player.setOrientation(wide?0:1);player.setPadding(dp(12),dp(8),dp(12),dp(8));shell.addView(player,new LinearLayout.LayoutParams(-1,0,1));cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackground(bg(0xff45576e,0xff161b28,24));cover.setImageResource(android.R.drawable.ic_media_play);cover.setClipToOutline(true);player.addView(cover,wide?new LinearLayout.LayoutParams(0,-1,1):new LinearLayout.LayoutParams(-1,0,1));LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);controls.setGravity(16);controls.setPadding(dp(14),dp(4),dp(14),dp(4));player.addView(controls,wide?new LinearLayout.LayoutParams(0,-1,1.5f):new LinearLayout.LayoutParams(-1,-2));track=label("ยังไม่ได้เลือกเพลง",24);track.setMaxLines(2);controls.addView(track);artist=label("เพลงในเครื่อง",14);controls.addView(artist);progress=new SeekBar(this);controls.addView(progress);progress.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){}public void onStartTrackingTouch(SeekBar s){dragging=true;}public void onStopTrackingTouch(SeekBar s){dragging=false;Intent i=new Intent(MainActivity.this,PlayerService.class).setAction("SEEK").putExtra("ms",s.getProgress());startService(i);}});clock=label("0:00 / 0:00",12);controls.addView(clock);LinearLayout row=new LinearLayout(this);controls.addView(row);action(row,"ก่อนหน้า",()->send("PREV"));action(row,"เล่น",()->send("PLAY"));action(row,"พัก",()->send("PAUSE"));action(row,"ถัดไป",()->send("NEXT"));LinearLayout extra=new LinearLayout(this);controls.addView(extra);action(extra,"สุ่ม",()->p.edit().putBoolean("shuffle",!p.getBoolean("shuffle",false)).apply());action(extra,"เล่นวน",()->p.edit().putBoolean("repeat",!p.getBoolean("repeat",true)).apply());SeekBar volume=new SeekBar(this);android.media.AudioManager am=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);volume.setMax(am.getStreamMaxVolume(3));volume.setProgress(am.getStreamVolume(3));controls.addView(label("ระดับเสียง",12));controls.addView(volume);volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){if(user)am.setStreamVolume(3,n,0);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});}
 String time(int ms){return String.format(java.util.Locale.US,"%d:%02d",ms/60000,(ms/1000)%60);}
 Runnable tick=new Runnable(){public void run(){int i=p.getInt("index",0);if(i!=shown&&i>=0&&i<songs.size()){shown=i;Uri u=Uri.parse(songs.get(i));track.setText(name(u));artist.setText("เพลงในเครื่อง");cover.setImageResource(android.R.drawable.ic_media_play);try{android.media.MediaMetadataRetriever m=new android.media.MediaMetadataRetriever();try{m.setDataSource(MainActivity.this,u);String t=m.extractMetadata(7),a=m.extractMetadata(2);if(t!=null)track.setText(t);if(a!=null)artist.setText(a);byte[] bytes=m.getEmbeddedPicture();if(bytes!=null){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inSampleSize=2;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(bitmap!=null){cover.setImageBitmap(bitmap);int color=bitmap.getPixel(bitmap.getWidth()/2,bitmap.getHeight()/2);shell.setBackground(bg(color,0xff10141d,0));}}}finally{m.release();}}catch(Exception e){}}int pos=p.getInt("position",0),dur=p.getInt("duration",0);if(!dragging){progress.setMax(Math.max(1,dur));progress.setProgress(pos);}clock.setText(time(pos)+" / "+time(dur));ui.postDelayed(this,1000);}};
 protected void onResume(){super.onResume();ui.removeCallbacks(tick);ui.post(tick);}protected void onPause(){ui.removeCallbacks(tick);super.onPause();}
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("music",0);try{JSONArray a=new JSONArray(p.getString("songs","[]"));for(int i=0;i<a.length();i++)songs.add(a.getString(i));}catch(Exception e){} ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(24,24,24,24);s.addView(root);shell=new LinearLayout(this);shell.setOrientation(1);shell.setBackground(bg(0xff303b50,0xff10141d,0));setContentView(shell);LinearLayout nav=new LinearLayout(this);shell.addView(nav);action(nav,"กำลังเล่น",()->showPage(false));action(nav,"เพลย์ลิสต์ / ตั้งค่า",()->showPage(true));buildPlayer();settings=new LinearLayout(this);settings.setOrientation(1);settings.addView(s,new LinearLayout.LayoutParams(-1,-1));shell.addView(settings,new LinearLayout.LayoutParams(-1,0,1));showPage(p.getBoolean("setupPage",false));TextView title=new TextView(this);title.setText("Kai Auto Music • v1.2");title.setTextSize(26);root.addView(title);button("+ เพิ่มไฟล์เพลง",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,1);});button("+ เพิ่มโฟลเดอร์และโฟลเดอร์ย่อย",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE),2));toggle("เล่นเพลงเมื่อเสียบชาร์จ","auto",true);toggle("หยุดเพลงเมื่อถอดชาร์จ","unplug",true);toggle("สุ่มเพลง","shuffle",false);toggle("เล่นวนเพลย์ลิสต์","repeat",true);toggle("เริ่มระบบหลังเปิดเครื่อง","boot",true);toggle("เล่นเพลงหลังเปิดเครื่องแม้ไม่ได้ชาร์จ","bootPlay",true);toggle("พยายามเปิดหน้าแอปอัตโนมัติ","launch",true);toggle("เล่นต่อจากตำแหน่งล่าสุด","resume",true);button("บันทึกเพลย์ลิสต์",()->playlist(true));button("โหลดเพลย์ลิสต์",()->playlist(false));button("บันทึกลิงก์ YouTube / YouTube Music",()->{EditText e=new EditText(this);e.setText(p.getString("youtube",""));new AlertDialog.Builder(this).setTitle("ลิงก์เพลย์ลิสต์").setView(e).setPositiveButton("บันทึก",(d,w)->p.edit().putString("youtube",e.getText().toString().trim()).apply()).setNegativeButton("ยกเลิก",null).show();});button("เปิดเพลย์ลิสต์ใน YouTube",()->{try{Uri u=Uri.parse(p.getString("youtube",""));if(!"https".equals(u.getScheme())||u.getHost()==null||!(u.getHost().equals("youtube.com")||u.getHost().endsWith(".youtube.com")||u.getHost().equals("youtu.be")))throw new Exception();startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"กรุณาบันทึกลิงก์ YouTube ที่ถูกต้อง",Toast.LENGTH_LONG).show();}});button("เปิดระบบอัตโนมัติ",()->send("ARM"));button("เล่นเพลง",()->send("PLAY"));button("หยุดชั่วคราว",()->send("PAUSE"));button("เพลงถัดไป",()->send("NEXT"));button("ปิดระบบอัตโนมัติ",()->{p.edit().putBoolean("armed",false).apply();stopService(new Intent(this,PlayerService.class));});button("ล้างเพลย์ลิสต์",()->{songs.clear();save();send("PAUSE");});list=new TextView(this);root.addView(list);refresh();s.post(()->s.scrollTo(0,p.getInt("scroll",0)));s.setOnScrollChangeListener((v,x,y,ox,oy)->p.edit().putInt("scroll",y).apply());}
 void playlist(boolean saveMode){if(saveMode){EditText e=new EditText(this);new AlertDialog.Builder(this).setTitle("ชื่อเพลย์ลิสต์").setView(e).setPositiveButton("บันทึก",(d,w)->{String n=e.getText().toString().trim();if(!n.isEmpty())getSharedPreferences("playlists",0).edit().putString(n,new JSONArray(songs).toString()).apply();}).setNegativeButton("ยกเลิก",null).show();}else{android.content.SharedPreferences q=getSharedPreferences("playlists",0);String[] names=q.getAll().keySet().toArray(new String[0]);new AlertDialog.Builder(this).setTitle("เลือกเพลย์ลิสต์").setItems(names,(d,w)->{stopService(new Intent(this,PlayerService.class));songs.clear();try{JSONArray a=new JSONArray(q.getString(names[w],"[]"));for(int i=0;i<a.length();i++)songs.add(a.getString(i));}catch(Exception e){}p.edit().putInt("index",0).putInt("position",0).apply();save();send("ARM");}).show();}}
 void button(String t,Runnable r){Button b=new Button(this);b.setText(t);b.setAllCaps(false);b.setBackground(bg(0xff303746,0xff222936,12));b.setTextColor(-1);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.setMargins(0,dp(3),0,dp(3));root.addView(b,bp);b.setOnClickListener(v->r.run());}void toggle(String t,String k,boolean d){Switch s=new Switch(this);s.setText(t);s.setChecked(p.getBoolean(k,d));root.addView(s);s.setOnCheckedChangeListener((v,c)->p.edit().putBoolean(k,c).apply());}
 void send(String a){Intent i=new Intent(this,PlayerService.class).setAction(a);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
 String name(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{"_display_name"},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception e){}return u.toString();}
 void add(Uri u,String n){if(n.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|mp4|wav|wave|flac|m4a|aac|ogg|opus|3gp|mkv|webm|amr)$")&&!songs.contains(u.toString()))songs.add(u.toString());}
 void walk(Uri tree,String id){Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,id);try(Cursor c=getContentResolver().query(children,new String[]{"document_id","_display_name","mime_type"},null,null,null)){while(c!=null&&c.moveToNext()){String child=c.getString(0);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2)))walk(tree,child);else add(DocumentsContract.buildDocumentUriUsingTree(tree,child),c.getString(1));}}}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null)return;try{if(r==2){Uri u=data.getData();getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);walk(u,DocumentsContract.getTreeDocumentId(u));}else if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)pick(data.getClipData().getItemAt(i).getUri());}else pick(data.getData());save();}catch(Exception e){Toast.makeText(this,e.toString(),Toast.LENGTH_LONG).show();}}
 void pick(Uri u){getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);add(u,name(u));}void save(){p.edit().putString("songs",new JSONArray(songs).toString()).apply();refresh();}void refresh(){shown=-1;StringBuilder b=new StringBuilder("เพลย์ลิสต์: "+songs.size()+" files\n");for(String u:songs)b.append(name(Uri.parse(u))).append('\n');list.setText(b);}
